def import_files_to_db_bdl_data() -> bool:
    """Importiert alle Dateien aus dem REPORT_FOLDER_PATH_BDL in die Datenbank.

    Verarbeitet Dateien nach Präfix,
    führt den jeweiligen Import und die Nachverarbeitung durch und verschiebt
    erfolgreich verarbeitete Dateien in den Zielordner.
    """
    # ==============================
    # Tabellenzuordung
    # ==============================

    #### (Präfix, Import-Funktion, Post-Processing-Funktion, zählt als bdl_reports_porcessed?)
    file_import_map: list[tuple[str, FileImportFunc, PostProcessFunc | None, bool]] = [
        (  # GP Fremdschlüssel
            "exp_fremdschl",
            lambda fp: handle_import(
                import_table, fp, "tb_bdl_fremdschluessel", "Nein", database="dbm_allgemein", seperator=";"
            ),
            None,
            False,
        ),
        (  # Kundendaten
            "exp_gepa",
            lambda fp: handle_import(
                import_table, fp, "tb_bdl_kunden", "Nein", database="dbm_allgemein", seperator=";"
            ),
            None,
            False,
        ),
        (  # Kundenhierachien
            "exp_hierarchien",
            lambda fp: handle_import(
                import_table, fp, "tb_bdl_hierachien", "Nein", database="dbm_allgemein", seperator=";"
            ),
            None,
            False,
        ),
        (  # Permissions
            "exp_perm",
            lambda fp: handle_import(
                import_table, fp, "tb_bdl_permission", "Nein", database="dbm_allgemein", seperator=";"
            ),
            None,
            False,
        ),
        (  # Vorgänge
            "exp_vorgaenge",
            lambda fp: handle_import(
                import_table, fp, "tb_bdl_vorgaenge", "Nein", database="dbm_allgemein", seperator=";"
            ),
            None,
            False,
        ),
        (  # VWAs
            "exp_vwa",
            lambda fp: handle_import(import_table, fp, "tb_bdl_vwa", "Nein", database="dbm_allgemein", seperator=";"),
            None,
            False,
        ),
    ]

    #### Dateien einlesen
    all_filenames = [
        f for f in os.listdir(REPORT_FOLDER_PATH_BDL) if os.path.isfile(os.path.join(REPORT_FOLDER_PATH_BDL, f))
    ]
    logger.info(f"Gefundene Dateien: {all_filenames}")
    print(f"Gefundene Dateien: {all_filenames}")

    # ==============================
    # Übertragung in die DB, inkl. Abspeichern der Dateien
    # ==============================

    # Für jeden Präfix in file_import_map die passenden Dateien chronologisch verarbeiten
    for prefix, func, post_func, dummy in iter_with_progress(
        logger,
        file_import_map,
        len(file_import_map),
        "Import-Praefixe",
    ):
        matching_files = sorted([f for f in all_filenames if f.startswith(prefix)])
        # logger.info(f"Verarbeite Präfix '{prefix}' ({len(matching_files)} datei(en)): {matching_files}")
        print(f"Verarbeite Präfix '{prefix}' ({len(matching_files)} datei(en)): {matching_files}")
        for filename in iter_with_progress(logger, matching_files, len(matching_files), f"Dateien fuer {prefix}"):
            filepath = os.path.join(REPORT_FOLDER_PATH_BDL, filename)
            processed = False

            try:
                # logger.info(f"Rufe Import-Funktion für {filename} auf")
                print(f"Rufe Import-Funktion für {filename} auf")
                result = func(filepath)
                # logger.info(f"Import-Ergebnis für {filename}: {result}")
                print(f"Import-Ergebnis für {filename}: {result}")
                processed = result is True

            except Exception as e:
                logger.error(f"Fehler beim Verarbeiten von {filename}: {e}", exc_info=True)
                # print(f"Fehler beim Verarbeiten von {filename}: {e}", exc_info=True)
                raise

            # Verschieben NUR bei erfolgreich verarbeiteten Dateien
            if processed:
                try:
                    os.rename(filepath, os.path.join(REPORT_TARGET_FOLDER_BDL, filename))
                    logger.info(f"datei {filename} erfolgreich verschoben")
                    # print(f"datei {filename} erfolgreich verschoben")
                except Exception as e:
                    logger.error(f"Fehler beim Verschieben von {filename}: {e}", exc_info=True)
                    # print(f"Fehler beim Verschieben von {filename}: {e}", exc_info=True)
                    raise
            else:
                # logger.warning(f"datei {filename} nicht verschoben - Verarbeitung nicht erfolgreich")
                print(f"datei {filename} nicht verschoben - Verarbeitung nicht erfolgreich")

        # Nachverarbeitung, falls definiert und Dateien vorhanden
        if post_func and matching_files:
            try:
                post_func()
            except Exception as e:
                # logger.error(f"Fehler bei der Nachverarbeitung nach '{prefix}': {e}", exc_info=True)
                print(f"Fehler bei der Nachverarbeitung nach '{prefix}': {e}", exc_info=True)
                raise

    return True


def generate_d365_accountreport(accountreport_processed: bool) -> bool:
    """Erzeugt den AccountReport für D365 wenn der AccountReport erfolgreich importiert wurde.

    Führt die accountbereinigung durch, exportiert den aufbereiteten AccountReport
    als CSV und aktualisiert den Last_Import-Timestamp.

    Args:
        accountreport_processed: Ob der AccountReport erfolgreich importiert wurde.

    Returns:
        True wenn der D365-AccountReport erfolgreich erzeugt wurde, sonst False.
    """

    accountreport_D365_processed = False

    # AccountReport für D365 erzeugen (nur wenn AccountReport verarbeitet wurde)
    result = execute_dataframe_query(
        """SELECT Date(Last_import) FROM tb_bewegungsdaten WHERE report = 'RECHNUNGSEMAIL'"""
    )
    if not result.empty:
        last_import_date = result.iloc[0, 0]
        today = datetime.now(TIMEZONE).date()

        if accountreport_processed and last_import_date is not None and last_import_date >= today:
            try:
                from ..api.esuite_cleanup import accountbereinigung

                accountbereinigung()
                abfrage = get_query_text("AUFBEREITUNG_ACCOUNT")
                datenbankabfrage_mit_export(
                    abfrage,
                    f"AccountReport-{datetime.now(TIMEZONE).strftime('%Y%m%d_%H%M%S')}",
                    FOLDER_ACC,
                    "CSV",
                    "Ja",
                )
                accountreport_D365_processed = True
            except Exception as e:
                logger.error(f"Fehler beim Ausführen von weitere_prozedur: {e}", exc_info=True)
                raise

            if accountreport_D365_processed:
                try:
                    update_last_updated("ACCOUNTREPORT", datetime.now(TIMEZONE).strftime("%Y-%m-%d %H:%M:%S"))
                except Exception as e:
                    logger.error(f"Fehler beim Update ACCOUNTREPORT: {e}", exc_info=True)
                    raise

    return accountreport_D365_processed


def upload_d365_accountreport() -> int:
    """Lädt die erzeugten AccountReport-CSV-Dateien auf den SFTP-Server hoch.

    Lädt alle CSV-Dateien aus FOLDER_ACC per SFTP hoch und verschiebt sie
    anschließend in den TARGET_FOLDER_ACC. Wartet 3 Minuten zwischen Uploads.

    Returns:
        Anzahl der erfolgreich hochgeladenen Dateien.
    """

    upload_count = 0
    sftp_config = get_sftp_account_config()

    csv_files = [
        f for f in os.listdir(FOLDER_ACC) if os.path.isfile(os.path.join(FOLDER_ACC, f)) and f.lower().endswith(".csv")
    ]
    for idx, filename in iter_with_progress(logger, enumerate(csv_files), len(csv_files), "D365-AccountReport-Uploads"):
        filepath = os.path.join(FOLDER_ACC, filename)
        upload_successful = False
        try:
            upload_file_to_sftp(
                file=filename,
                local_file_path=FOLDER_ACC,
                remote_file_path=sftp_config.remote_path,
                sftp_config=sftp_config,
            )
            upload_successful = True
            upload_count += 1
        except Exception as e:
            logger.error(f"Fehler beim Übertragen von {filename}: {e}", exc_info=True)
            raise

        if upload_successful:
            try:
                os.rename(filepath, os.path.join(TARGET_FOLDER_ACC, filename))
            except Exception as e:
                logger.error(f"Fehler beim Verschieben von {filename}: {e}", exc_info=True)
                raise

            if len(csv_files) > 1 and idx < len(csv_files) - 1:
                time.sleep(180)  # 3 Minuten Wartezeit zwischen Uploads

    return upload_count


def import_file_to_db(filepath: str, table_name: str, update_exclusion: str, database: str) -> bool:
    """Importiert eine datei in die Datenbank und führt die Nachverarbeitung durch.

    Args:
        filepath: Pfad zur zu importierenden datei.
        table_name: Name der Zieltabelle in der Datenbank.
        update_exclusion: Name der Spalte, die bei Updates ausgeschlossen werden soll.
                            Wenn "Nein", werden alle Spalten berücksichtigt.
        database: Name der Datenbank, in die die datei importiert werden soll.
    Returns:
        True wenn der Import und die Nachverarbeitung erfolgreich waren, sonst False.
    """
    logger.info(
        "Importiere datei %s in tabelle %s (Update Exclusion: %s, Datenbank: %s)",
        filepath,
        table_name,
        update_exclusion,
        database,
    )
    try:
        if table_name == "tb_customersupportlog":
            import_result = import_customersupportlog(filepath)
        else:
            import_result = import_table(filepath, table_name, update_exclusion, database)
            if table_name == "tb_accountreport_faktur" and import_result is True:
                post_accountreport()
            elif table_name == "tb_orderreport_faktur" and import_result is True:
                post_orderreport()
            elif table_name == "tb_subscriptionsreport_ff" and import_result is True:
                post_subscriptions()
        return import_result is True
    except Exception as e:
        logger.error(f"Fehler beim Importieren von {filepath} in {table_name}: {e}", exc_info=True)
        raise


def _prepare_bundle_summary(
    bundles: list[dict[str, Any]],
    subscriptions: list[dict[str, Any]],
    umgebung: str,
) -> list[dict[str, Any]]:
    """Bereitet die Bundle-Cart-Daten für den DB-Import auf.

    Args:
        bundles: Liste der Bundle-Objekte aus der API.
        subscriptions: Liste der Subscription-Objekte aus der API.
        umgebung: Umgebungsbezeichner ('Prod' oder 'Test').

    Returns:
        Liste von Dicts mit den aufbereiteten Zeilen.
    """
    bundle_map = {b["bundleReference"]: b.get("name", "N/A") for b in bundles}
    subscription_map = {s["contractReference"]: s for s in subscriptions}

    summary_data: list[dict[str, Any]] = []
    for bundle in bundles:
        for cart in bundle.get("carts", []):
            contract_reference = cart.get("contractReference", "N/A")
            subscription = subscription_map.get(contract_reference, {})
            for line_item in cart.get("lineItems", []):
                pricing = line_item.get("pricing", {})
                summary_data.append(
                    {
                        "bundleCartReference": cart.get("cartReference", "N/A"),
                        "bundleReference": bundle.get("bundleReference", "N/A"),
                        "bundleTitle": bundle_map.get(bundle.get("bundleReference"), "N/A"),
                        "bundleDescription": bundle.get("description", "N/A"),
                        "bundleContractReference": contract_reference,
                        "ContractTitle": subscription.get("subscriptionTitle", "N/A"),
                        "ContractDescription": subscription.get("subscriptionDescription", "N/A"),
                        "cartLineItemReference": line_item.get("lineItemReference", "N/A"),
                        "cartLineItemDescription": line_item.get("description", "N/A"),
                        "productReference": line_item.get("productInfo", {}).get("productReference", "N/A"),
                        "productQuantity": line_item.get("quantity", "N/A"),
                        "lineItemGrossAmount": pricing.get("grossAmount", "N/A"),
                        "Umgebung": umgebung,
                    }
                )
    return summary_data


def product_bundles(resthost: str | None = None, headers: dict[str, str] | None = None) -> None:
    """Laedt Produkt- und Preisdaten aus der eSuite-API in die Datenbank.

    Args:
        resthost: Optionale Basis-URL der eSuite-API. Wenn nicht gesetzt,
            wird die Produktiv-URL aus der gemeinsamen Konfiguration geladen.
        headers: Optionale HTTP-Header fuer die eSuite-API. Wenn nicht gesetzt,
            werden die Produktiv-Header aus der gemeinsamen Konfiguration geladen.
    """
    if resthost is None or headers is None:
        resthost = RESTHOST_PROD if resthost is None else resthost
        headers = get_esuite_api_config("PROD").headers if headers is None else headers

    warnings.filterwarnings("ignore", category=InsecureRequestWarning)
    url = resthost + "products"

    response = retry_request("GET", url, headers=headers, verify=False)
    if response is None:
        logger.error("Produktdaten konnten nicht abgerufen werden.")
        return

    data = response.json()
    products = [
        {
            "ProductReference": product.get("productReference", ""),
            "Name": product.get("name", ""),
            "Description": product.get("description", ""),
            "Type": product.get("type", ""),
            "status": product.get("status", ""),
            "CreatedDate": product.get("createdDate", ""),
            "LastUpdatedDate": product.get("lastUpdatedDate", ""),
            "PriceRole": price.get("role", ""),
            "PriceAmount": price.get("amount", ""),
            "IsGross": price.get("isGross", ""),
            "PriceReference": price.get("priceReference", ""),
            "TaxCategory": price.get("taxCategory", ""),
            "PaymentMethod": price.get("paymentMethod", ""),
            "Currency": price.get("currency", ""),
        }
        for product in data
        for price in product.get("pricing", [])
    ]

    df = pd.DataFrame(products)
    if not df.empty:
        save_df_to_db(df, "tb_productreferences", "Nein")


def bundle_carts(umgebung: str) -> None:
    """Laedt Bundle-Cart-Referenzen fuer eine eSuite-Umgebung in die Datenbank.

    Args:
        umgebung: Umgebung fuer den API-Abruf, erlaubt sind ``"Prod"`` und ``"Test"``.

    Raises:
        ValueError: Wenn die Umgebung nicht unterstuetzt wird.
    """
    env_config: dict[str, BundleCartConfig] = {
        "Prod": {
            "BUNDLES_URL": BUNDLES_URL_PROD,
            "SUBSCRIPTIONS_URL": SUBSCRIPTIONS_URL_PROD,
            "environment": "PROD",
        },
        "Test": {
            "BUNDLES_URL": BUNDLES_URL_UAT,
            "SUBSCRIPTIONS_URL": SUBSCRIPTIONS_URL_UAT,
            "environment": "UAT",
        },
    }

    if umgebung not in env_config:
        raise ValueError("Ungültige Umgebung. Bitte 'Prod' oder 'Test' angeben.")

    config = env_config[umgebung]
    headers = get_esuite_api_config(config["environment"]).headers
    warnings.filterwarnings("ignore", category=InsecureRequestWarning)

    try:
        bundles_resp = retry_request("GET", config["BUNDLES_URL"], headers=headers, verify=False)
        if bundles_resp is None:
            logger.error("Bundles konnten nicht abgerufen werden.")
            return
        bundles = bundles_resp.json()

        if not any("bundleReference" in b for b in bundles):
            logger.warning("Keine Service-Referenzen gefunden.")
            return

        subs_resp = retry_request("GET", config["SUBSCRIPTIONS_URL"], headers=headers, verify=False)
        if subs_resp is None:
            logger.error("Subscriptions konnten nicht abgerufen werden.")
            return
        subscriptions = subs_resp.json()

        summary_data = _prepare_bundle_summary(bundles, subscriptions, umgebung)
        if not summary_data:
            logger.warning("Keine Daten zum Speichern vorhanden.")
            return

        save_df_to_db(pd.DataFrame(summary_data), "tb_bundlecartreferences", "Nein")

    except Exception as e:
        logger.error(f"Fehler in bundlecarts: {e}", exc_info=True)


def update_tb_preise() -> bool:
    """Aktualisiert die Preistabelle ueber die gespeicherte Datenbankprozedur.

    Returns:
        True wenn die prozedur erfolgreich ausgefuehrt wurde, sonst False.
    """
    connection = None
    try:
        connection = connect_to_db()
        if not connection:
            logging.error("Keine Datenbankverbindung hergestellt!")
            return False  # Falls keine Verbindung hergestellt werden konnte, keine Berechtigung

        with connection.cursor() as cursor:
            cursor.callproc("input_tb_preise")
            connection.commit()
            return True

    finally:
        # Verbindung immer schließen, wenn sie existiert
        if connection:
            connection.close()
            logging.info("Verbindung zur Datenbank geschlossen.")
